const countryLocaleMap = {
  GB: 'en-GB', IE: 'en-GB', AU: 'en-GB', NZ: 'en-GB',
  US: 'en-US', CA: 'en-US', SG: 'en-SG',
  DE: 'de', AT: 'de', CH: 'de', NL: 'nl', BE: 'nl',
  FR: 'fr', IT: 'it', ES: 'es', PT: 'pt', PL: 'pl',
  SE: 'sv', NO: 'no', DK: 'da', FI: 'fi', GR: 'el', CY: 'el',
  HR: 'hr', SI: 'sl', SK: 'sk', CZ: 'cs', HU: 'hu', IL: 'he'
};

const languageAliasMap = {
  en: 'en-GB', 'en-gb': 'en-GB', 'en-us': 'en-US', 'en-sg': 'en-SG',
  de: 'de', nl: 'nl', fr: 'fr', it: 'it', es: 'es', pt: 'pt', pl: 'pl',
  sv: 'sv', no: 'no', nb: 'no', nn: 'no', da: 'da', fi: 'fi', el: 'el',
  hr: 'hr', sl: 'sl', sk: 'sk', cs: 'cs', hu: 'hu', he: 'he', iw: 'he'
};

const select = document.getElementById('languageSelect');
const modal = document.getElementById('legalModal');
const modalTitle = document.getElementById('modalTitle');
const modalText = document.getElementById('modalText');
let currentLocale = 'en-GB';

function normaliseLocale(input) {
  if (!input) return null;
  const lower = String(input).replace('_', '-').toLowerCase();
  if (locales[input]) return input;
  if (languageAliasMap[lower]) return languageAliasMap[lower];
  const base = lower.split('-')[0];
  return languageAliasMap[base] || null;
}

function renderSelect() {
  select.innerHTML = Object.entries(locales)
    .map(([code, locale]) => `<option value="${code}">${locale.name}</option>`)
    .join('');
}

function setLocale(code, { persist = false } = {}) {
  const safeCode = locales[code] ? code : 'en-GB';
  const dictionary = locales[safeCode];
  currentLocale = safeCode;

  document.documentElement.lang = safeCode;
  document.documentElement.dir = dictionary.dir;
  document.title = dictionary.metaTitle;
  const description = document.querySelector('meta[name="description"]');
  if (description) description.content = dictionary.heroText;

  document.querySelectorAll('[data-i18n]').forEach((node) => {
    const key = node.dataset.i18n;
    if (dictionary[key]) node.textContent = dictionary[key];
  });

  dictionary.profiles.forEach(([name, city], index) => {
    document.querySelectorAll(`[data-profile="${index}-name"]`).forEach((node) => node.textContent = name);
    document.querySelectorAll(`[data-profile="${index}-city"]`).forEach((node) => node.textContent = city);
  });

  select.value = safeCode;
  updateAffiliateLinks();

  if (persist) localStorage.setItem('heartmatch-language', safeCode);
}

function trackingParams() {
  const allowed = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'sub1', 'sub2', 'sub3', 'clickid', 'fbclid'];
  const current = new URLSearchParams(location.search);
  const output = new URLSearchParams();
  allowed.forEach((key) => {
    const value = current.get(key);
    if (value) output.set(key, value);
  });
  output.set('lang', currentLocale);
  return output;
}

function affiliateUrl(slot) {
  const params = trackingParams();
  params.set('slot', slot || 'unknown');
  return `/api/go?${params.toString()}`;
}

function updateAffiliateLinks() {
  document.querySelectorAll('.js-affiliate').forEach((element) => {
    const url = affiliateUrl(element.dataset.slot);
    if (element.tagName === 'A') element.href = url;
    element.dataset.href = url;
  });
}

async function detectInitialLocale() {
  const queryLocale = normaliseLocale(new URLSearchParams(location.search).get('lang'));
  if (queryLocale) return { code: queryLocale, persist: false };

  const storedLocale = normaliseLocale(localStorage.getItem('heartmatch-language'));
  if (storedLocale) return { code: storedLocale, persist: false };

  try {
    const response = await fetch('/api/geo', { headers: { accept: 'application/json' } });
    if (response.ok) {
      const data = await response.json();
      const geoLocale = countryLocaleMap[String(data.country || '').toUpperCase()];
      if (geoLocale) return { code: geoLocale, persist: false };
    }
  } catch (_) {}

  const browserLocales = navigator.languages?.length ? navigator.languages : [navigator.language];
  for (const browserLocale of browserLocales) {
    const matched = normaliseLocale(browserLocale);
    if (matched) return { code: matched, persist: false };
  }

  return { code: 'en-GB', persist: false };
}

select.addEventListener('change', () => {
  setLocale(select.value, { persist: true });
  const url = new URL(location.href);
  url.searchParams.set('lang', select.value);
  history.replaceState({}, '', url);
});

document.querySelectorAll('.heart-button.js-affiliate').forEach((button) => {
  button.addEventListener('click', () => { location.href = button.dataset.href; });
});

document.querySelectorAll('[data-modal]').forEach((button) => {
  button.addEventListener('click', () => {
    const dictionary = locales[currentLocale];
    const type = button.dataset.modal;
    modalTitle.textContent = dictionary[`${type}Title`];
    modalText.textContent = dictionary[`${type}Text`];
    modal.showModal();
  });
});

document.querySelector('.modal-close').addEventListener('click', () => modal.close());
modal.addEventListener('click', (event) => {
  const bounds = modal.getBoundingClientRect();
  const outside = event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom;
  if (outside) modal.close();
});

renderSelect();
setLocale(normaliseLocale(navigator.language) || 'en-GB');
detectInitialLocale().then(({ code, persist }) => setLocale(code, { persist }));
